import "jsr:@supabase/functions-js/edge-runtime.d.ts";
const CORS={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization, x-client-info, apikey, content-type","Access-Control-Allow-Methods":"POST, OPTIONS","Content-Type":"application/json"};
const CLIENT="ecommerce-agent-sandbox-v1"; const URL=Deno.env.get("SUPABASE_URL")!; const KEY=Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
async function db(path:string,init:RequestInit={}){return fetch(URL+"/rest/v1/"+path,{...init,headers:{apikey:KEY,Authorization:"Bearer "+KEY,"Content-Type":"application/json",Prefer:init.method==="POST"?"return=minimal":"return=representation"}});}
const sleep=(ms:number)=>new Promise(r=>setTimeout(r,ms));
type Opp={id:string;name:string;strategy:string;pressure:number;adaptation:number;lastAction:string;lastResponse:string};
const ACTIONS=["CHANGE_KEYWORD","CHANGE_TARGETING","INCREASE_BID","HOLD","CHANGE_PRICE","INCREASE_BUDGET","DECREASE_BID"];
function weightedPick(items:{value:string,p:number}[],seed:number){const total=items.reduce((s,x)=>s+x.p,0);let x=((seed*9301+49297)%233280)/233280*total;for(const item of items){x-=item.p;if(x<=0)return item.value}return items[items.length-1].value}
function chooseAction(i:number,state:any,opps:Opp[],ctx:any={}){const prev=state?.lastRound||{},crowding=Number(state?.crowding||.1),marginal=Number(state?.marginalRoi||3.5),response=prev.actual_opponent_response;const guided=String(ctx?.action||"");const allowed=ACTIONS.includes(guided);if(allowed && !prev.stop_signal && marginal>=1.7)return guided;if(prev.stop_signal||marginal<1.7)return "HOLD";if(response==="MATCH_PRICE")return crowding>.5?"CHANGE_TARGETING":"CHANGE_KEYWORD";if(response==="RAISE_BID")return "CHANGE_KEYWORD";if(response==="DEFEND_TRAFFIC")return "CHANGE_TARGETING";if(response==="SHIFT_TO_CONTENT")return "CHANGE_KEYWORD";if(response==="HOLD")return i%3===0?"INCREASE_BID":"CHANGE_TARGETING";const strongest=opps.slice().sort((a,b)=>b.pressure-a.pressure)[0];if(strongest?.strategy==="PRICE_WAR")return "CHANGE_TARGETING";return ACTIONS[(i*7+opps.length)%ACTIONS.length]}
function responseBranches(action:string,opps:Opp[]){const b:any[]=[];const price=opps.find(o=>o.strategy==="PRICE_WAR"),traffic=opps.find(o=>o.strategy==="TRAFFIC_DEFENSE"),content=opps.find(o=>o.strategy==="CONTENT_SHIFT");const add=(response:string,p:number,nextActionHint:string)=>b.push({response,p,nextActionHint,stopCondition:"边际ROI下降、现金/库存约束升高或竞争压力连续两轮恶化",expansionCondition:"边际ROI稳定、现金/库存安全且对手压力未继续上升"});if(action==="CHANGE_PRICE")add("MATCH_PRICE",.55+(price?.pressure||0)*.25,"CHANGE_TARGETING");else if(action==="INCREASE_BID"||action==="INCREASE_BUDGET")add("RAISE_BID",.42+(traffic?.pressure||0)*.32,"CHANGE_KEYWORD");else if(action==="CHANGE_KEYWORD"||action==="CHANGE_TARGETING")add("DEFEND_TRAFFIC",.36+(traffic?.pressure||0)*.18,"CHANGE_TARGETING");else add("HOLD",.35,"HOLD");add("SHIFT_TO_CONTENT",.18+(content?.pressure||0)*.22,"CHANGE_KEYWORD");add("HOLD",Math.max(.12,1-b.reduce((s,x)=>s+x.p,0)),"HOLD");return b}
function updateOpponents(opps:Opp[],action:string,actual:string){return opps.map(o=>{let pressure=o.pressure,adaptation=o.adaptation;if((o.strategy==="PRICE_WAR"&&action==="CHANGE_PRICE")||(o.strategy==="TRAFFIC_DEFENSE"&&(action==="INCREASE_BID"||action==="INCREASE_BUDGET"))||(o.strategy==="CONTENT_SHIFT"&&(action==="CHANGE_KEYWORD"||action==="CHANGE_TARGETING")))pressure=Math.min(1,pressure+.14);else pressure=Math.max(.05,pressure-.035);adaptation=Math.min(1,adaptation+(o.lastResponse===actual?.05:.02));let lr="HOLD";if(o.strategy==="PRICE_WAR")lr=action==="CHANGE_PRICE"?"MATCH_PRICE":"HOLD";if(o.strategy==="TRAFFIC_DEFENSE")lr=(action==="INCREASE_BID"||action==="INCREASE_BUDGET")?"RAISE_BID":"DEFEND_TRAFFIC";if(o.strategy==="CONTENT_SHIFT")lr=(action==="CHANGE_KEYWORD"||action==="CHANGE_TARGETING")?"SHIFT_TO_CONTENT":"HOLD";return {...o,pressure,adaptation,lastAction:action,lastResponse:lr}})}
function strategyForUs(action:string,prev:string,stop:boolean){const map:any={CHANGE_KEYWORD:["关键词迁移/错位竞争","上一轮对手提高流量防守或内容转移，避开正面竞价","利用搜索意图/长尾与场景词寻找低拥挤流量"],CHANGE_TARGETING:["定向切换/流量绕行","对手价格或流量防守增强，降低正面冲突","把预算转向竞争压力较低的人群/场景"],INCREASE_BID:["阶段性抢量","当前边际ROI仍安全且需要验证流量弹性","小幅增加出价观察对手是否跟价"],CHANGE_PRICE:["价格试探","需要测试价格战阈值","观察竞品是否跟价并测算价格战成本"],INCREASE_BUDGET:["预算扩张试探","当前单位经济仍满足扩张条件","逐步放量而非一次性满仓"],DECREASE_BID:["降价退出竞争","流量竞争成本过高","降低竞价保护现金流"],HOLD:["等待/观察","风险或边际收益不足以支持扩张","不新增风险，等待下一轮信号"]};const x=map[action]||["自适应策略",prev||"当前市场状态","观察反馈"];return {strategy:x[0],trigger:x[1],rationale:x[2],stopRule:stop?"立即停止扩张":"若边际ROI继续下降则降级/停止"}}
function opponentStep(o:Opp,action:string,actual:string){const s=o.strategy==="PRICE_WAR"?"价格战防守":o.strategy==="TRAFFIC_DEFENSE"?"流量防守":o.strategy==="CONTENT_SHIFT"?"内容迁移":"观察";const hit=o.lastResponse===actual;const rationale=o.strategy==="PRICE_WAR"?(action==="CHANGE_PRICE"?"我方触发价格战阈值，选择跟价":"暂不跟价，保留价格战能力"):o.strategy==="TRAFFIC_DEFENSE"?((action==="INCREASE_BID"||action==="INCREASE_BUDGET")?"我方抢量，直接抬高流量竞争":"保护核心流量入口"):o.strategy==="CONTENT_SHIFT"?((action==="CHANGE_KEYWORD"||action==="CHANGE_TARGETING")?"我方改变流量入口，转向内容承接":"保持内容阵地"):"先观察";return {participant:o.id,name:o.name,strategy:s,strategyCode:o.strategy,action:o.lastResponse,rationale,trigger:hit?"我方动作命中其防守条件":"当前动作未命中其主要防守条件",responseToUs:actual,pressure:Number(o.pressure.toFixed(3)),adaptation:Number(o.adaptation.toFixed(3)),nextLikelyStrategy:s}}
function round(i:number,state:any,opps:Opp[],ctx:any={}){const prev=state?.lastRound||{},action=chooseAction(i,state,opps,ctx),branches=responseBranches(action,opps),actual=prev.stop_signal?"HOLD":weightedPick(branches.map(x=>({value:x.response,p:x.p})),i*17+Math.round((state?.marginalRoi||3)*10)),next=(branches.find(x=>x.response===actual)||branches[0]).nextActionHint,roi=Math.max(2.05,4.62-i*.105+(actual==="HOLD"?.06:0)-(actual==="RAISE_BID"?.08:0)),spend=Math.round((42+i*9+(action==="HOLD"?-8:0))*100)/100,marginal=Math.max(.72,roi-i*.11-(actual==="RAISE_BID"?.18:0)),crowding=Math.min(.9,.12+i*.042+(actual==="RAISE_BID"?.08:0)),stop=marginal<1.65||crowding>.72,rev=Math.round(spend*roi*100)/100,conv=Math.max(1,Math.round(rev/82)),updated=updateOpponents(opps,action,actual),us=strategyForUs(action,prev.action,stop),opponentSteps=updated.map(o=>opponentStep(o,action,actual)),strategySteps=[{order:1,actor:"OUR_AGENT",actorName:"我方Agent",strategy:us.strategy,action,rationale:us.rationale,trigger:us.trigger,result:"等待对手响应",nextStrategy:next},{order:2,actor:"OPP-01",actorName:"价格型竞品",...opponentSteps[0]},{order:3,actor:"OPP-02",actorName:"流量型竞品",...opponentSteps[1]},{order:4,actor:"OPP-03",actorName:"内容型竞品",...opponentSteps[2]}];return {round:i,action,recommended_action:action,breakthrough:actual==="MATCH_PRICE"?"TRAFFIC":actual==="RAISE_BID"?"CONVERSION":actual==="SHIFT_TO_CONTENT"?"CONTENT":"TRAFFIC",risk_approved:!stop,risk_mode:(action==="INCREASE_BID"||action==="INCREASE_BUDGET")?"CONDITIONAL":"ALLOW",decision_score:Math.max(.58,.86-i*.012),spend,revenue:rev,conversions:conv,roi,marginal_roi:marginal,crowding,bid_escalation:action==="INCREASE_BID"?1+i*.025:1,price_war:actual==="MATCH_PRICE"?.34:.1,stock_constraint:Math.min(.8,.08+i*.024),cash_constraint:Math.min(.7,.06+i*.018),stop_signal:stop,stop_reason:stop?"边际ROI下降或竞争拥挤超过安全阈值":null,opponent_actions:updated.map(o=>o.lastResponse),opponent_model:{strategy:updated.slice().sort((a,b)=>b.pressure-a.pressure)[0]?.strategy||"ADAPTIVE",strongestPressure:Math.max(...updated.map(o=>o.pressure))},learning:{useful:!stop,calibrationError:Math.round(Math.abs(3.65-roi)*100)/100},risk_dimensions:{funding:"LOW",unitEconomics:stop?"HIGH":"MEDIUM",market:crowding>.55?"HIGH":"MEDIUM",opponent:actual==="RAISE_BID"?"HIGH":"MEDIUM"},post_market_risk:{level:stop?"HIGH":"MEDIUM",mode:stop?"AUTO_DISABLED":"MONITOR",approved:!stop},response_branches:branches,actual_opponent_response:actual,next_action_hint:next,opponent_participants:updated.map((o,idx)=>({...o,action:o.lastResponse,strategyDetail:strategySteps[idx+1]})),strategy_steps:strategySteps,decision_tree:{type:"ADAPTIVE_GAME_TREE",round:i,ourAction:action,actualResponse:actual,nextActionHint:next,executedPath:[...(state?.executedPath||[]),{round:i,action,response:actual,nextAction:next,strategy:us.strategy}],branches:branches.map(x=>({...x,selected:x.response===actual})),strategySteps,opponentState:updated.map(o=>({id:o.id,name:o.name,strategy:o.strategy,pressure:Number(o.pressure.toFixed(3)),adaptation:Number(o.adaptation.toFixed(3)),lastResponse:o.lastResponse})),transitionReason:prev.actual_opponent_response?"基于上一轮真实响应 "+prev.actual_opponent_response+" 自适应切换":"首轮基于当前对手状态选择"}}}
async function runSimulation(id:string,n:number,ctx:any={}){try{let state:any={executedPath:[],strategyContext:ctx};let opps:Opp[]=[{id:"OPP-01",name:"价格型竞品",strategy:"PRICE_WAR",pressure:.34,adaptation:.45,lastAction:"INIT",lastResponse:"HOLD"},{id:"OPP-02",name:"流量型竞品",strategy:"TRAFFIC_DEFENSE",pressure:.48,adaptation:.52,lastAction:"INIT",lastResponse:"DEFEND_TRAFFIC"},{id:"OPP-03",name:"内容型竞品",strategy:"CONTENT_SHIFT",pressure:.29,adaptation:.38,lastAction:"INIT",lastResponse:"HOLD"}];for(let i=1;i<=n;i++){await sleep(1200);const r=round(i,state,opps,ctx);opps=r.opponent_participants.map((o:any)=>({id:o.id,name:o.name,strategy:o.strategy,pressure:o.pressure,adaptation:o.adaptation,lastAction:o.lastAction,lastResponse:o.lastResponse}));state={lastRound:r,crowding:r.crowding,marginalRoi:r.marginal_roi,executedPath:r.decision_tree.executedPath};const p=Math.round(i/n*100),stamp=new Date().toISOString();const roundRow={run_id:id,round:r.round,action:r.action,recommended_action:r.recommended_action,breakthrough:r.breakthrough,risk_approved:r.risk_approved,risk_mode:r.risk_mode,decision_score:r.decision_score,spend:r.spend,revenue:r.revenue,conversions:r.conversions,roi:r.roi,marginal_roi:r.marginal_roi,crowding:r.crowding,bid_escalation:r.bid_escalation,price_war:r.price_war,stock_constraint:r.stock_constraint,cash_constraint:r.cash_constraint,stop_signal:r.stop_signal,stop_reason:r.stop_reason,opponent_actions:r.opponent_actions,opponent_model:r.opponent_model,learning:r.learning,risk_dimensions:r.risk_dimensions,post_market_risk:r.post_market_risk,response_branches:r.response_branches,actual_opponent_response:r.actual_opponent_response,next_action_hint:r.next_action_hint,created_at:stamp};const rr=await db("sandbox_agent_rounds",{method:"POST",body:JSON.stringify(roundRow)});if(!rr.ok)throw new Error("sandbox_agent_rounds 写入失败: "+await rr.text());const marketRows=[{name:"竞争拥挤度",signal_type:"COMPETITION",strength:r.crowding>.72?"HIGH":r.crowding>.5?"MEDIUM":"LOW",detail:"当前竞争拥挤度 "+r.crowding},{name:"边际ROI",signal_type:"UNIT_ECONOMICS",strength:r.marginal_roi<1.65?"NEGATIVE":r.marginal_roi<2?"MEDIUM":"POSITIVE",detail:"当前边际ROI "+r.marginal_roi},{name:"对手响应",signal_type:"OPPONENT_RESPONSE",strength:"OBSERVED",detail:"实际响应 "+r.actual_opponent_response}];for(const m of marketRows){const z=await db("sandbox_market_signals",{method:"POST",body:JSON.stringify({run_id:id,...m,created_at:stamp})});if(!z.ok)throw new Error("sandbox_market_signals 写入失败: "+await z.text());}const bt=await db("sandbox_backtests",{method:"POST",body:JSON.stringify({run_id:id,scenario:"连续博弈第"+i+"轮",rounds:i,roi:r.roi,risk:r.post_market_risk?.level||"MEDIUM",action:r.action,created_at:stamp})});if(!bt.ok)throw new Error("sandbox_backtests 写入失败: "+await bt.text());const mem=await db("sandbox_memories",{method:"POST",body:JSON.stringify({run_id:id,memory_type:"ROUND_LEARNING",content:"第"+i+"轮：我方"+r.action+" → 实际响应"+r.actual_opponent_response+" → 下一动作"+r.next_action_hint,confidence:r.learning?.useful?0.8:0.5,status:"ACTIVE",created_at:stamp})});if(!mem.ok)throw new Error("sandbox_memories 写入失败: "+await mem.text());await db("sandbox_runs?id=eq."+id,{method:"PATCH",body:JSON.stringify({status:i===n?"completed":"running",agent_progress:p,updated_at:stamp,state:{mode:"SANDBOX",currentRound:i,totalRounds:n,latestAction:r.action,latestOpponentResponse:r.actual_opponent_response,nextActionHint:r.next_action_hint,stopSignal:r.stop_signal,executedPath:r.decision_tree.executedPath,opponentState:opps}})});const riskRows=[{metric:"risk_approved",value:r.risk_approved},{metric:"risk_mode",value:r.risk_mode},{metric:"risk_level",value:r.post_market_risk?.level||null},{metric:"risk_dimensions",value:r.risk_dimensions||null},{metric:"marginal_roi",value:r.marginal_roi},{metric:"crowding",value:r.crowding},{metric:"stop_signal",value:r.stop_signal},{metric:"stop_reason",value:r.stop_reason||null}];for(const rv of riskRows){const res=await db("sandbox_risk_results",{method:"POST",body:JSON.stringify({run_id:id,metric:rv.metric,value:rv.value,created_at:stamp})});if(!res.ok)throw new Error("sandbox_risk_results 写入失败: "+await res.text());}await db("sandbox_runs?id=eq."+id,{method:"PATCH",body:JSON.stringify({risk_progress:p,updated_at:stamp})});await db("sandbox_task_results?run_id=eq."+id,{method:"PATCH",body:JSON.stringify({status:i===n?"completed":"running",progress:p})});await db("sandbox_events",{method:"POST",body:JSON.stringify({run_id:id,event_type:"AGENT_ROUND",title:"第 "+i+" 轮完成",detail:r.action+"["+usText(r.strategy_steps[0])+"] → "+r.opponent_participants.map((o:any)=>o.name+":"+o.action).join(" / "),payload:{round:i,strategySteps:r.strategy_steps,action:r.action,opponent:r.actual_opponent_response,nextAction:r.next_action_hint,stop:r.stop_signal,adaptive:true},created_at:stamp})})}}catch(e){await db("sandbox_runs?id=eq."+id,{method:"PATCH",body:JSON.stringify({status:"failed",updated_at:new Date().toISOString(),state:{error:String(e)}})});await db("sandbox_events",{method:"POST",body:JSON.stringify({run_id:id,event_type:"AGENT_FAILED",title:"Agent Sandbox 执行失败",detail:String(e),payload:{error:String(e)},created_at:new Date().toISOString()})})}}
function usText(x:any){return x?.strategy||"ADAPTIVE"}
Deno.serve(async req=>{if(req.method==="OPTIONS")return new Response("ok",{headers:CORS});try{const b=await req.json().catch(()=>({}));if(b.client_key!==CLIENT)return new Response(JSON.stringify({error:"sandbox client_key required"}),{status:403,headers:CORS});const n=Math.min(30,Math.max(3,Number(b.rounds)||10)),strategyContext=b.strategy_context||{},id=crypto.randomUUID(),now=new Date().toISOString();await db("sandbox_runs",{method:"POST",body:JSON.stringify({id,client_key:CLIENT,status:"running",agent_progress:0,backtest_progress:0,risk_progress:0,memory_count:0,run_count:1,state:{mode:"SANDBOX",startedAt:now,totalRounds:n,strategyContext}})});await db("sandbox_task_results",{method:"POST",body:JSON.stringify({run_id:id,task_id:"agent-"+id,task_type:"AGENT_SIMULATION",status:"running",progress:0,created_at:now})});await db("sandbox_events",{method:"POST",body:JSON.stringify({run_id:id,event_type:"AGENT_STARTED",title:"Agent Sandbox 开始模拟",detail:"自适应博弈模拟已启动：每一轮展示我方策略→三类对手策略→实际响应→下一策略",payload:{rounds:n,adaptive:true,showStrategySteps:true},created_at:now})});EdgeRuntime.waitUntil(runSimulation(id,n,strategyContext));return new Response(JSON.stringify({ok:true,run_id:id,rounds:n,status:"running",adaptive:true,showStrategySteps:true}),{headers:CORS})}catch(e){return new Response(JSON.stringify({error:String(e)}),{status:500,headers:CORS})}});
